// 2026-09-09, real live-test finding: n8n has no built-in "prevent
// overlapping executions" setting. A real test session fired 5 separate
// manual executions within 53 seconds (14:18:00-14:18:53) -- each one
// independently made its own real Gemini call with zero coordination
// between them, blowing straight through the free-tier quota regardless
// of the per-execution batching/throttling fix added earlier the same day
// (that fix only paces calls *within* one execution). This uses n8n's
// workflow static data (persists across executions of the same workflow,
// in n8n's own DB) as a real lock: acquire it here, skip the whole run if
// another one is still active. STALE_MS is a safety net, not the primary
// mechanism -- if a previous run crashed or was killed without a normal
// end, the lock would otherwise never release; 10 minutes is generous
// against this workflow's real worst case (8 attachments, 13s-spaced
// classify + submit stages, observed ~3 minutes end to end) without
// risking a permanently stuck lock. The lock is deliberately NOT released
// at every terminal node (there are ~15 of them across this workflow;
// missing even one would silently defeat the lock) -- staleness expiry is
// the one release path that cannot be missed by a future edit here.
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const STALE_MS = 10 * 60 * 1000;

if (staticData.flow0LockAcquiredAt && (now - staticData.flow0LockAcquiredAt) < STALE_MS) {
  return [{
    json: {
      locked: true,
      lockAgeSeconds: Math.round((now - staticData.flow0LockAcquiredAt) / 1000),
    },
  }];
}

staticData.flow0LockAcquiredAt = now;
return [{ json: { locked: false } }];

// H1's original 2026-09-02 policy for this workflow was local-AI-only, no
// exceptions. Superseded 2026-09-09: H1 decided Unternehmen X goes full
// cloud-gemini, grounded in a real capacity study (see the project decision log)
// (real steady-state volume is ~1000x under Gemini's free-tier daily quota,
// even Flow 0's extra classification calls included) -- same decision that
// already made Flow 1b's extraction lane cloud-first. No silent default
// either way, though: UNTERNEHMEN_X_FLOW0_CLASSIFICATION_PROFILE must be
// explicitly "local-default" or "cloud-gemini" (see "Check Flow 0
// Classification Profile (Message)"), same discipline as Flow 1b's
// UNTERNEHMEN_X_AI_EXECUTION_PROFILE below -- Unternehmen X's real .env sets
// cloud-gemini; local-default stays available (e.g. for a future tenant
// that has not consented to a 3rd-party AI provider). Building both
// request bodies here is free (no API call yet); the profile check
// downstream decides which one actually gets sent.
//
// Prompt revised 2026-09-09 (real live-test finding, H1-reported): a real
// test email with the word "invoice" three times in the subject/body
// ("invoice sammlung invoice ... invoice sammlungen") and 8 real invoice
// PDF attachments was still classified "has no invoice" by Gemini -- the
// original prompt only ever saw body text and effectively required a real
// invoice narrative, not just an invoice-related label. Since this
// classifier is only a cheap pre-filter before the real detector
// (per-attachment vision classification downstream), it must fail toward
// "has invoice" under real uncertainty, not against it: a false "has
// invoice" costs one extra (correctly filtered) attachment check: a false
// "has no invoice" silently drops a real invoice with zero downstream
// trace. hasAttachments (already present on the message object itself, no
// extra API call needed) is now passed explicitly so the model knows
// attachments exist even though it cannot see their content.
function buildMessagePrompt(hasAttachments) {
  var base = 'Classify the following email into exactly one category: "has invoice" or "has no invoice". This is a cheap pre-filter before a separate check looks at any attachments, so treat "has invoice" as the safe default whenever there is real uncertainty -- only answer "has no invoice" when you are confident this is clearly unrelated to invoices (e.g. spam, a newsletter, an out-of-office reply, internal chat with no billing content).';
  var attachmentNote = hasAttachments
    ? ' This email HAS file attachments -- you cannot see their content, but any real invoice is very likely inside one of them rather than narrated in the text below. Treat any invoice-related word anywhere in the subject/body (even just a label like "invoice" or "Rechnung" with no further narrative) as sufficient evidence to answer "has invoice".'
    : ' This email has NO attachments, so an invoice can only exist if it is actually described in the text below.';
  return base + attachmentNote + ' Output JSON only, no markdown fences, in the form {"category": "has invoice"} or {"category": "has no invoice"}.\n\nEmail text:\n';
}

return items.map(item => {
  const text = item.json.markdown || '';
  const hasAttachments = item.json.hasAttachments === true;
  const prompt = buildMessagePrompt(hasAttachments) + text;
  return {
    json: {
      localRequest: {
        model: $env.LOCAL_LLM_MODEL,
        temperature: 0,
        messages: [
          { role: 'user', content: prompt },
        ],
      },
      geminiRequest: {
        contents: [
          { parts: [{ text: prompt }] },
        ],
      },
    },
  };
});

function extractText(item) {
  const j = item.json || {};
  const parts = j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts;
  if (Array.isArray(parts) && parts[0] && typeof parts[0].text === 'string') {
    return parts[0].text;
  }
  throw new Error('Could not find Gemini text output in expected candidates[0].content.parts[0].text field.');
}

function stripFences(text) {
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

return items.map((item, index) => {
  const original = $('Get All Messages from one specific Mail-Folder').itemMatching(index).json;
  const raw = extractText(item);
  const cleaned = stripFences(raw);

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Gemini message-classification output is not valid JSON. Raw output: ${cleaned}`);
  }

  return {
    json: {
      ...original,
      category: parsed.category === 'has invoice' ? 'has invoice' : 'has no invoice',
    },
  };
});

function extractText(item) {
  const j = item.json || {};
  if (
    Array.isArray(j.choices) &&
    j.choices[0] &&
    j.choices[0].message &&
    typeof j.choices[0].message.content === 'string'
  ) {
    return j.choices[0].message.content;
  }
  throw new Error('Could not find local LLM text output in expected choices[0].message.content field.');
}

function stripFences(text) {
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

// The chain since "Markdown" (Build Message Classification Request ->
// Classify Message Locally, an httpRequest node whose JSON response
// replaces $json entirely) has discarded the original message's own
// fields -- id, subject, sender, etc. Recovered here from the original
// list node. Must use itemMatching(index), not the bare .item shorthand:
// this Code node runs once for ALL items, so $('NodeName').item (no
// index) always resolves to the SAME fixed item regardless of which item
// the current .map() iteration is on -- confirmed live 2026-09-02 with a
// real 2-message batch, where both items silently ended up with the
// first message's subject/id. itemMatching(index) uses n8n's real
// pairedItem lineage instead of a naive fixed/positional lookup.
return items.map((item, index) => {
  const original = $('Get All Messages from one specific Mail-Folder').itemMatching(index).json;
  const raw = extractText(item);
  const cleaned = stripFences(raw);

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Local LLM message-classification output is not valid JSON. Raw output: ${cleaned}`);
  }

  // Fail closed: anything other than exactly "has invoice" is treated as
  // "has no invoice" -- never assume a message needs processing on an
  // ambiguous or unexpected model answer.
  return {
    json: {
      ...original,
      category: parsed.category === 'has invoice' ? 'has invoice' : 'has no invoice',
    },
  };
});

// "Claim Message" (the move above) replaces $json with just {success:
// true} and drops the downloaded attachment binary entirely -- neither
// n8n's docs/UI make this obvious (confirmed live 2026-09-04). Recover
// both the message fields AND the binary attachments from "Download
// Attachments", the last node that actually had them, via
// itemMatching(index) -- not the bare .item shorthand, which always
// resolves to a fixed item regardless of loop position in a Code node
// that runs once for all items.
return items.map((item, index) => {
  const original = $('Download Attachments').itemMatching(index);
  return { json: original.json, binary: original.binary };
});

// Inherited from the legacy prototype, but $input.first().json.id was
// wrong for a multi-message batch: it always points at the FIRST message
// in the whole input, not the message the outer loop is currently on,
// silently pairing every attachment after the first with the wrong
// message's metadata (confirmed live 2026-09-02 with a real 2-message
// batch -- downstream, "Merge Attachment + Message Metadata by
// messageId" then fails to match the mispaired item and drops it).
// item.json.id is the current message's own id, matching how
// metadata/subject/sender are already correctly read from `item.json`
// two lines below.
let results = [];

for (const item of $input.all()) {
	if (!item.binary) continue;

	const metadata = item.json;

	for (const key of Object.keys(item.binary)) {
		results.push({
			json: {
				fileName: item.binary[key].fileName,
				messageId: item.json.id,
				subject: metadata.subject,
				senderName: metadata.sender?.emailAddress?.name || '',
				senderEmail: metadata.sender?.emailAddress?.address || '',
				receivedAt: metadata.receivedAt,
				webLink: metadata.webLink
			},
			binary: {
				data: item.binary[key]
			}
		});
	}
}

return results;

const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  results.push({
    json: {
      ...item.json,
      attachmentBase64: buffer.toString('base64'),
      attachmentMimeType: item.binary.data.mimeType,
    },
    binary: item.binary,
  });
}
return results;

// H1's original 2026-09-02 policy for this workflow was local-AI-only, no
// exceptions. Superseded 2026-09-09: H1 decided Unternehmen X goes full
// cloud-gemini (a real capacity study (see the project decision log), same
// decision that already made Flow 1b's extraction lane cloud-first). No
// silent default either way: UNTERNEHMEN_X_FLOW0_CLASSIFICATION_PROFILE must be
// explicitly "local-default" or "cloud-gemini" (see "Check Flow 0
// Classification Profile (Attachment)"). Building both request bodies here
// is free (no API call yet); the profile check downstream decides which
// one actually gets sent.
const PROMPT = 'You are an accounts receivable agent helping to identify whether an email attachment is an invoice. Look at the image and answer: (1) is_invoice: is this document an invoice? (2) is_issued_to_company: is this invoice addressed/issued to the buyer company (not some unrelated document)? Output JSON only, no markdown fences, exactly in the form {"is_invoice": true, "is_issued_to_company": true}.';

return items.map(item => {
  // Came from the render branch (PDF -> PNG) or the passthrough branch
  // (already an image) -- either way, one image to classify.
  const base64 = item.json.pngBase64 !== undefined ? item.json.pngBase64 : item.json.attachmentBase64;
  const mimeType = item.json.pngBase64 !== undefined ? 'image/png' : item.json.attachmentMimeType;

  return {
    json: {
      localRequest: {
        model: $env.LOCAL_LLM_MODEL,
        temperature: 0,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'text', text: PROMPT },
              { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64}` } },
            ],
          },
        ],
      },
      geminiRequest: {
        contents: [
          {
            parts: [
              { inline_data: { mime_type: mimeType, data: base64 } },
              { text: PROMPT },
            ],
          },
        ],
      },
    },
    binary: item.binary,
  };
});

function extractText(item) {
  const j = item.json || {};
  const parts = j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts;
  if (Array.isArray(parts) && parts[0] && typeof parts[0].text === 'string') {
    return parts[0].text;
  }
  throw new Error('Could not find Gemini text output in expected candidates[0].content.parts[0].text field.');
}

function stripFences(text) {
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

return items.map(item => {
  const raw = extractText(item);
  const cleaned = stripFences(raw);

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Gemini attachment-classification output is not valid JSON. Raw output: ${cleaned}`);
  }

  return {
    json: {
      is_invoice: parsed.is_invoice === true,
      is_issued_to_company: parsed.is_issued_to_company === true,
    },
  };
});

function extractText(item) {
  const j = item.json || {};
  if (
    Array.isArray(j.choices) &&
    j.choices[0] &&
    j.choices[0].message &&
    typeof j.choices[0].message.content === 'string'
  ) {
    return j.choices[0].message.content;
  }
  throw new Error('Could not find local LLM text output in expected choices[0].message.content field.');
}

