  }

  return {
    json: {
      is_invoice: parsed.is_invoice === true,
      is_issued_to_company: parsed.is_issued_to_company === true,
    },
  };
});

// Only Unternehmen X's own real buyer master data (fetched moments ago from its
// own published OrganizationBaseline) is forwarded -- never a demo fixture.
const organizationId = $env.UNTERNEHMEN_X_TCMS_ORGANIZATION_ID;

// n8n's httpRequest node replaces the item with its HTTP response -- it
// does not pass through pre-existing binary. "Detect Invoice Format" and
// "Fetch Unternehmen X Buyer Master Data" are both httpRequest nodes sitting
// between the attachment and here, so item.binary is empty by this point
// (confirmed live 2026-09-02: "Submit to Flow 1a/1b" failed with "input
// data [does not] contain a binary file 'data'"). Recovered from the last
// node that still had it. Must use itemMatching(index), not the bare
// .item shorthand -- this Code node runs once for ALL items, so
// $('NodeName').item (no index) always resolves to the SAME fixed item
// regardless of loop position (confirmed live 2026-09-02: with a multi-
// attachment batch this silently attached the FIRST attachment's file to
// every submission instead of each item's own file). itemMatching(index)
// uses n8n's real pairedItem lineage instead of a naive fixed lookup.
return items.map((item, index) => ({
  json: {
    phase1ProfileKey: organizationId,
    tcmsOrganizationId: organizationId,
    buyerMasterData: JSON.stringify(item.json.buyerMasterData),
    controlProfileId: item.json.controlProfileId,
  },
  binary: $('Merge Attachment + Message Metadata by messageId').itemMatching(index).binary,
}));

